import base64
import json
import os
from dataclasses import dataclass
from typing import Any, Dict, Optional, Union

from cryptography.hazmat.primitives.ciphers.aead import AESGCM

import boto3
from botocore.client import BaseClient


@dataclass
class EnvelopeEncryptedPayload:
    kms_key_id: str
    ciphertext_blob_b64: str
    encrypted_data_key_b64: str
    nonce_b64: str
    algorithm: str = "AES-256-GCM"
    kms_provider: str = "aws-kms"

    def to_json(self) -> str:
        return json.dumps(
            {
                "kms_provider": self.kms_provider,
                "kms_key_id": self.kms_key_id,
                "algorithm": self.algorithm,
                "ciphertext_blob_b64": self.ciphertext_blob_b64,
                "encrypted_data_key_b64": self.encrypted_data_key_b64,
                "nonce_b64": self.nonce_b64,
            }
        )

    @staticmethod
    def from_json(data: Union[str, bytes]) -> "EnvelopeEncryptedPayload":
        if isinstance(data, bytes):
            data = data.decode("utf-8")
        obj = json.loads(data)
        return EnvelopeEncryptedPayload(
            kms_key_id=obj["kms_key_id"],
            ciphertext_blob_b64=obj["ciphertext_blob_b64"],
            encrypted_data_key_b64=obj["encrypted_data_key_b64"],
            nonce_b64=obj["nonce_b64"],
            algorithm=obj.get("algorithm", "AES-256-GCM"),
            kms_provider=obj.get("kms_provider", "aws-kms"),
        )


def _kms_client(region_name: Optional[str] = None) -> BaseClient:
    return boto3.client("kms", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"))


def envelope_encrypt(
    plaintext: Union[str, bytes],
    kms_key_id: str,
    aad: Optional[Union[str, bytes]] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    if isinstance(plaintext, str):
        plaintext_bytes = plaintext.encode("utf-8")
    else:
        plaintext_bytes = plaintext

    if aad is None:
        aad_bytes = b""
    elif isinstance(aad, str):
        aad_bytes = aad.encode("utf-8")
    else:
        aad_bytes = aad

    kms = _kms_client(region_name=region_name)

    response = kms.generate_data_key(
        KeyId=kms_key_id,
        KeySpec="AES_256",
    )
    data_key_plaintext = response["Plaintext"]
    data_key_encrypted = response["CiphertextBlob"]

    nonce = os.urandom(12)
    aesgcm = AESGCM(data_key_plaintext)
    ciphertext = aesgcm.encrypt(nonce, plaintext_bytes, aad_bytes)

    return {
        "kms_provider": "aws-kms",
        "kms_key_id": kms_key_id,
        "algorithm": "AES-256-GCM",
        "ciphertext_blob_b64": base64.b64encode(ciphertext).decode("utf-8"),
        "encrypted_data_key_b64": base64.b64encode(data_key_encrypted).decode("utf-8"),
        "nonce_b64": base64.b64encode(nonce).decode("utf-8"),
    }


def envelope_decrypt(
    payload: Union[EnvelopeEncryptedPayload, Dict[str, Any], str, bytes],
    aad: Optional[Union[str, bytes]] = None,
    region_name: Optional[str] = None,
) -> bytes:
    if isinstance(payload, (str, bytes)):
        payload_obj = EnvelopeEncryptedPayload.from_json(payload)
    elif isinstance(payload, EnvelopeEncryptedPayload):
        payload_obj = payload
    else:
        payload_obj = EnvelopeEncryptedPayload(
            kms_key_id=payload["kms_key_id"],
            ciphertext_blob_b64=payload["ciphertext_blob_b64"],
            encrypted_data_key_b64=payload["encrypted_data_key_b64"],
            nonce_b64=payload["nonce_b64"],
            algorithm=payload.get("algorithm", "AES-256-GCM"),
            kms_provider=payload.get("kms_provider", "aws-kms"),
        )

    if isinstance(aad, str):
        aad_bytes = aad.encode("utf-8")
    elif aad is None:
        aad_bytes = b""
    else:
        aad_bytes = aad

    kms = _kms_client(region_name=region_name)

    encrypted_data_key = base64.b64decode(payload_obj.encrypted_data_key_b64)
    ciphertext = base64.b64decode(payload_obj.ciphertext_blob_b64)
    nonce = base64.b64decode(payload_obj.nonce_b64)

    response = kms.decrypt(CiphertextBlob=encrypted_data_key, KeyId=payload_obj.kms_key_id)
    data_key_plaintext = response["Plaintext"]

    aesgcm = AESGCM(data_key_plaintext)
    plaintext = aesgcm.decrypt(nonce, ciphertext, aad_bytes)
    return plaintext


def envelope_encrypt_json(
    plaintext: Union[str, bytes],
    kms_key_id: str,
    aad: Optional[Union[str, bytes]] = None,
    region_name: Optional[str] = None,
) -> str:
    return json.dumps(envelope_encrypt(plaintext, kms_key_id, aad=aad, region_name=region_name))


def envelope_decrypt_json(
    encrypted_json: Union[str, bytes],
    aad: Optional[Union[str, bytes]] = None,
    region_name: Optional[str] = None,
) -> str:
    plaintext = envelope_decrypt(encrypted_json, aad=aad, region_name=region_name)
    return plaintext.decode("utf-8")
